/* —— 底部输入框（默认展开，可点圆点切换） + 右下角小圆点唤出 —— */
html[data-dsh-composer="hidden"] .wSkVaW_composerSeat,
html[data-dsh-composer="hidden"] .wSkVaW_composerStack,
html[data-dsh-composer="hidden"] [data-composer-seat]{display:none !important}
#dsh-composer-dot{
  position:fixed;right:10px;bottom:10px;z-index:2147483000;
  width:26px;height:26px;padding:0;border-radius:50%;cursor:pointer;
  border:1px solid color-mix(in srgb, currentColor 22%, transparent);
  background:color-mix(in srgb, currentColor 8%, transparent);
  color:inherit;font:12px/1 system-ui,sans-serif;
  display:flex;align-items:center;justify-content:center;
  opacity:.35;transition:opacity .15s ease, bottom .15s ease;
}
#dsh-composer-dot:hover{opacity:1}

/* dsh-light-enforce（2026-09-22）：强制**浅色**（原为强制深色，用户反馈黑底白字刺眼）。
   DSH 浅色就是 body 默认档，只要不被加上深色属性即可。 */
html{color-scheme:light !important}
body{color-scheme:light !important}
/* 消息气泡：用户附件里的蓝 #cce6ff + 深色字 */
.Sixlwa_bubble{background:#cce6ff !important;color:#0f1012 !important}

/* dsh-hide-thinking（2026-09-22 用户要求）：关闭「思考过程」的显示。
   ⚠️ 只隐藏显示，不关模型推理能力（reasoningEffort 不动）——不损失回答质量。 */
.lcKema_root{display:none !important}

/* dsh-conclusion-card（2026-09-22）：把回答末尾的引用块渲染成深色「结论卡」。
   与总结弹窗同一套配色：底 #22252b / 竖条 #4d8dff / 字白。
   人设（cordis.patch.yml 的 personaPrefix）要求每轮以引用块收尾。 */
.EvIC1a_scroll [class*="_markdown_"] blockquote{
  background:#22252b !important; color:#ffffff !important;
  border:none !important; border-left:3px solid #4d8dff !important;
  border-radius:10px !important; padding:12px 15px !important;
  margin:14px 0 4px !important;
  box-shadow:0 2px 10px rgba(0,0,0,.10) !important;
  font-size:15px !important; line-height:23px !important;
}
.EvIC1a_scroll [class*="_markdown_"] blockquote,
.EvIC1a_scroll [class*="_markdown_"] blockquote p,
.EvIC1a_scroll [class*="_markdown_"] blockquote li{color:#c8cdd4 !important}
.EvIC1a_scroll [class*="_markdown_"] blockquote strong,
.EvIC1a_scroll [class*="_markdown_"] blockquote b{color:#ffffff !important;font-weight:600 !important}
.EvIC1a_scroll [class*="_markdown_"] blockquote a{color:#8ab4ff !important}
.EvIC1a_scroll [class*="_markdown_"] blockquote p{margin:0 !important}
.EvIC1a_scroll [class*="_markdown_"] blockquote p + p{margin-top:6px !important}
/* 卡内代码（2026-09-23 修正）：
   ⚠️ 原来用 filter:invert 做"深底可读"，实测**适得其反**：
      行内 code 的 computed 背景是浅色(250,250,250)、字色继承卡片(200,205,212)，
      反相后变成"深底 + 深字" → 用户看不清（截图圈出来了）。
   正解：**去掉反转**，改成"浅底 + 深字"——
      行内 code 显式给浅色底 + 固定深色字（行内代码没有语法高亮，安全）；
      代码块保留 DSH 原生浅底，用强制深色兜底（shiki 高亮多为中深色，在浅底上可读；
      若个别高亮色偏浅，比"整块看不清"仍好得多）。 */
.EvIC1a_scroll [class*="_markdown_"] blockquote code{
  background:rgba(255,255,255,.92) !important;
  color:#0f1115 !important;
}
.EvIC1a_scroll [class*="_markdown_"] blockquote code *{color:#0f1115 !important}
.EvIC1a_scroll [class*="_markdown_"] blockquote pre{
  background:#f9fafb !important;
  border:1px solid rgba(255,255,255,.14) !important;
}
.EvIC1a_scroll [class*="_markdown_"] blockquote pre code,
.EvIC1a_scroll [class*="_markdown_"] blockquote pre code *{background:transparent !important}

/* —— 全局字号/留白（2026-09-21 定；2026-09-22 收编进补丁）—— */
#root{zoom:1 !important}
html{-webkit-text-size-adjust:160% !important;text-size-adjust:160% !important}
.EvIC1a_scroll{padding-left:4px !important;padding-right:4px !important}
.uV2eYG_root{padding-left:4px !important;padding-right:4px !important}
.bOPqQW_root{padding-left:4px !important;padding-right:4px !important}
.bOPqQW_root, .bOPqQW_root *{font-size:5px !important;line-height:1.5 !important}
/* 2026-09-22：消息操作条缩到一半（原作者意图），但**必须同时隐藏它的
   悬浮提示气泡** —— 否则那个 tooltip（"复制"）会飘在页面左边中间。
   原因：tooltip 的 left/top 是按**未缩放**坐标写进 inline style 的，
   而父容器被 zoom:0.5 缩放 → 位置算错；且触屏没有 hover 去隐藏它
   → 永久可见。实测：气泡固定在 (0,333)、31x20、黑底白字。
   触屏上 tooltip 本来就无用，直接 display:none。 */
.xzv4MW_actions{zoom:0.5}
._bubble_1nw3t_1{display:none !important}
.lcKema_root, .lcKema_root *{font-size:6.5px !important}
/* dsh-hide-thinking（2026-09-22 用户要求）：关闭"思考过程"的显示。
   ⚠️ 只隐藏显示，**不关模型的推理能力**（reasoningEffort 保持不动）——
      推理继续做，只是不给用户看，这样不损失回答质量。
   前端「思考」块的根类就是 .lcKema_root（其下有 lcKema_thinkBody），
   整个块连外壳一起隐藏。想恢复：删掉这条或改成 display:block。 */
.lcKema_root{display:none !important}

/* dsh-shrink-content（2026-09-22）：工具卡片（代码/读取/写入/编辑/搜索）+
   上下文注入 + bash + others（任务列表等），与「思考」同字号 6.5px（渲染 9.6px） */
.o3BgMG_root, .o3BgMG_root *,
.CY-8Ka_root[data-variant="bash"], .CY-8Ka_root[data-variant="bash"] *,
.XrJvXW_root, .XrJvXW_root *,
._5OnbHa_root, ._5OnbHa_root *{font-size:6.5px !important;line-height:1 !important}

/* dsh-tight-blocks:begin（2026-09-22 v4）
   ① 正文/气泡行距 1.4（保持正常）；
   ② 内容块（卡片/任务列表/工具调用条目）压到最小：
      - 卡片文字 + 「思考」都 line-height:1；
      - 卡片行高写死 24px（._row_luwio_16，文字只有 ~10px）→ 用 App 自带变量
        --dsh-content-font-delta:-9px：行高 24→15px、图标 16→7px、svg 14→5px，
        行内留白 14→5px（≈1/3）；再往下文字/图标会被 overflow:hidden 裁掉；
      - 变量只在卡片作用域里设，不碰正文（正文用 body 上的默认值，设 :root 会被 body 覆盖）；
      - 子调用 margin 4/2→1/1、row-gap 4→1px；消息行 margin 16→1px；
      - 块内段落/列表 margin 2px、pre 上下 padding 2px；
   ③ 表格行距也压到最小：th/td line-height 1（15.6px）、上下 padding 10px→1px。 */
.EvIC1a_scroll *{line-height:1.4 !important}
.lcKema_root, .lcKema_root *,
.o3BgMG_root, .o3BgMG_root *,
.CY-8Ka_root[data-variant="bash"], .CY-8Ka_root[data-variant="bash"] *,
.XrJvXW_root, .XrJvXW_root *,
._5OnbHa_root, ._5OnbHa_root *{line-height:1 !important}
.EvIC1a_scroll table, .EvIC1a_scroll table *{line-height:1 !important}
.EvIC1a_scroll th, .EvIC1a_scroll td{padding-top:1px !important;padding-bottom:1px !important}
.EvIC1a_scroll ._root_luwio_9,
.lcKema_root, .o3BgMG_root, .CY-8Ka_root, .XrJvXW_root, ._5OnbHa_root{
  --dsh-content-font-size:6.5px !important;
  --dsh-content-font-size-secondary:6.5px !important;
  --dsh-content-font-delta:-9px !important;
}
.ztWv_q_subCalls{margin-top:1px !important;margin-bottom:1px !important;row-gap:1px !important}
.EvIC1a_flowItem{margin-top:1px !important}
.o3BgMG_root p, .o3BgMG_root ol, .o3BgMG_root ul, .o3BgMG_root li,
.CY-8Ka_root p, .CY-8Ka_root ol, .CY-8Ka_root ul, .CY-8Ka_root li,
.XrJvXW_root p, .XrJvXW_root ol, .XrJvXW_root ul, .XrJvXW_root li,
._5OnbHa_root p, ._5OnbHa_root ol, ._5OnbHa_root ul, ._5OnbHa_root li{margin-top:2px !important;margin-bottom:2px !important}
.o3BgMG_root pre, .CY-8Ka_root pre, .XrJvXW_root pre, ._5OnbHa_root pre{padding-top:2px !important;padding-bottom:2px !important}
/* dsh-tight-blocks:end */

/* dsh-terminal-tight（2026-09-23）：新版「终端卡」（bash/命令输出）压小。
   背景：用户截图反馈"返回代码信息这块字号太大、行距太大"。
   实测（CDP 读 App WebView 真实 DOM 的 computed style）：
     头部 CY-8Ka_root 仍被旧规则覆盖，但**内容体被拆成了独立节点**：
       CY-8Ka_card > CY-8Ka_bodyWrap > _block_1gdtu_1.CY-8Ka_terminal
         > _header_1gdtu_32（_prompt_1gdtu_70 / _promptLine_1gdtu_78 /
                              _cwd_1gdtu_108 / _command_1gdtu_116 /
                              _runStateLabel_1gdtu_99 / _copyButton_1gdtu_143）
         > _output_1gdtu_156 > _line_1gdtu_180
     这些节点**不在 .CY-8Ka_root 之下** → 旧规则够不着
     → 继承正文 20px（渲染 24px / 行高 33.6px），一屏放不下几行。
   取值：10px / 行高 12px（渲染 ≈12px / 14.4px，约正文的一半）。
   特异性：html body 前缀 → (0,3,0)，稳赢正文那条 :where(...) 的 (0,1,0)。 */
html body .EvIC1a_scroll .CY-8Ka_card,
html body .EvIC1a_scroll .CY-8Ka_card *,
html body .EvIC1a_scroll .CY-8Ka_bodyWrap,
html body .EvIC1a_scroll .CY-8Ka_bodyWrap *,
html body .EvIC1a_scroll .CY-8Ka_terminal,
html body .EvIC1a_scroll .CY-8Ka_terminal *,
html body .EvIC1a_scroll [class*="_1gdtu_"],
html body .EvIC1a_scroll [class*="_1gdtu_"] *{
  font-size:10px !important; line-height:12px !important;
}
/* 卡内留白一起收（头部那条最占地方） */
html body .EvIC1a_scroll ._header_1gdtu_32{padding:2px 6px !important;min-height:0 !important}
html body .EvIC1a_scroll ._output_1gdtu_156,
html body .EvIC1a_scroll ._line_1gdtu_180{padding-top:0 !important;padding-bottom:0 !important;margin:0 !important}
html body .EvIC1a_scroll .CY-8Ka_card{margin-top:2px !important;margin-bottom:2px !important;border-radius:6px !important}
/* 工具调用折叠组头（"32 次工具调用 · 5 条消息"）同属代码信息块：一起压小 */
html body .EvIC1a_scroll [class*="l_V-RG_"]{font-size:10px !important;line-height:12px !important}

/* dsh-body-font-bump（2026-09-22；2026-09-24 用户要求"再小一点点" → 20px 改 18px）：正文 18px（渲染 21.6px）。
   正文原本靠"继承浏览器默认字号 + text-size-adjust:160%"自动放大，
   CSS 里没有可调基准 → 只能显式给字号。
   ⚠️ 用 :where() 包裹那串 :not()：否则特异性飙到 (0,13,0)，
      会压死后面的代码块/表格规则（2026-09-22 踩过）。
   ⚠️ 排除项里要含 .md-code-block 和表格，否则它们会被正文规则覆盖。 */
.EvIC1a_scroll,
.EvIC1a_scroll :where(:not(.lcKema_root):not(.lcKema_root *):not(.o3BgMG_root):not(.o3BgMG_root *):not(.CY-8Ka_root):not(.CY-8Ka_root *):not(.XrJvXW_root):not(.XrJvXW_root *):not(._5OnbHa_root):not(._5OnbHa_root *):not(._root_luwio_9):not(._root_luwio_9 *):not(.md-code-block):not(.md-code-block *):not(table):not(table *)){
  font-size:18px !important;
}

/* dsh-codeblock-tight（2026-09-22）：代码块与行内代码压到最小。
   shiki 把代码切成 span.line，只压外层压不住内层 → 一并覆盖。 */
.EvIC1a_scroll .md-code-block pre,
.EvIC1a_scroll .md-code-block pre code,
.EvIC1a_scroll .md-code-block code,
.EvIC1a_scroll .md-code-block pre code .line,
.EvIC1a_scroll .md-code-block pre code span,
.EvIC1a_scroll pre._plain_rsn9u_103,
.EvIC1a_scroll pre._plain_rsn9u_103 code,
.EvIC1a_scroll pre._plain_rsn9u_103 code .line,
.EvIC1a_scroll ._content_rsn9u_74 pre,
.EvIC1a_scroll ._content_rsn9u_74 code{
  font-size:11px !important; line-height:13px !important;
}
.EvIC1a_scroll [class*="_markdown_"] :not(pre) > code,
.EvIC1a_scroll [class*="_markdown_"] :not(pre) > code *{
  font-size:11px !important; line-height:16px !important; padding:0 3px !important;
}
.EvIC1a_scroll .md-code-block pre{padding:2px 5px !important}
.EvIC1a_scroll .md-code-block ._content_rsn9u_74{padding:0 !important}
.EvIC1a_scroll .md-code-block ._bannerWrap_rsn9u_24{padding:0 !important;min-height:0 !important}
.EvIC1a_scroll .md-code-block{margin-top:3px !important;margin-bottom:3px !important;border-radius:6px !important}

/* dsh-tooltip-off（2026-09-22）：隐藏 tooltip 气泡。
   现象：页面左边中间永久飘着一块黑底白字「复制」小卡片。
   根因：① patch_fonts 给 .xzv4MW_actions 加了 zoom:0.5；
         ② tooltip 的 left/top 按**未缩放**坐标写进 inline style，
            父容器缩放后位置算错，飘到页面左边；
         ③ 触屏无 hover → tooltip 永不被隐藏，永久可见。
   触屏上 tooltip 本就无用，直接隐藏。 */
._bubble_1nw3t_1{display:none !important}

/* dsh-table-tight（2026-09-22）：表格 15px（渲染 18px）/ 行高 20px，
   右 padding 16 → 8px（列更靠拢、少换行）。 */
.EvIC1a_scroll [class*="_markdown_"] table,
.EvIC1a_scroll [class*="_markdown_"] table th,
.EvIC1a_scroll [class*="_markdown_"] table td,
.EvIC1a_scroll [class*="_tableScroll_"] table,
.EvIC1a_scroll [class*="_tableScroll_"] th,
.EvIC1a_scroll [class*="_tableScroll_"] td{
  font-size:15px !important; line-height:20px !important;
}
.EvIC1a_scroll [class*="_markdown_"] th,
.EvIC1a_scroll [class*="_markdown_"] td,
.EvIC1a_scroll [class*="_tableScroll_"] th,
.EvIC1a_scroll [class*="_tableScroll_"] td{
  padding-top:0 !important; padding-bottom:0 !important; padding-right:8px !important;
}
.EvIC1a_scroll [class*="_tableScroll_"] table code{font-size:13px !important;line-height:16px !important}

/* DSB 的 frame/root/panel 都吃 --dsw-alias-bg-base；改 token 比改哈希类名稳。
   深色档给参考配色深色的同款值（0 0% 8% = #141414），避免深色下被强制成暖白。 */
body { --dsw-alias-bg-base: #F7F6F3 !important; }
body[data-ds-dark-theme] { --dsw-alias-bg-base: #141414 !important; }

/* Reserve the fixed rail control's own lane; never overlay the brand. */
.hHd-Xa_logoRow { padding-left:32px !important; }
.hHd-Xa_brandName { letter-spacing:0 !important; }
.hHd-Xa_brandName::after { content:none !important; }
@media (max-width:600px) {
  [role="menu"] ._shortcut_4ub78_198 { display:none !important; }
  /* Statistics are optional detail, not clipped fragments on a phone. */
  [data-composer-stat] { display:none !important; }
  .uV2eYG_row { flex-wrap:wrap !important; gap:8px !important; }
  .uV2eYG_trailing { flex:1 1 100% !important; min-width:0 !important; }
  .uV2eYG_standardControls { flex:1 !important; min-width:0 !important; }
  ._7KE1Ra_root { flex:1 !important; min-width:0 !important; }
  ._7KE1Ra_trigger {
    max-width:100% !important; height:auto !important; min-height:28px;
    flex-wrap:wrap !important; row-gap:2px;
  }
  ._7KE1Ra_triggerLabel {
    display:block !important;
    white-space:normal !important; overflow:visible !important;
    overflow-wrap:anywhere; text-overflow:clip !important;
  }
  ._7KE1Ra_triggerEffort {
    display:block !important; flex:0 0 auto !important;
    white-space:nowrap !important; overflow:visible !important;
    overflow-wrap:normal; text-overflow:clip !important;
  }
  ._7KE1Ra_triggerIcon { display:none !important; }
  ._7KE1Ra_triggerLabel ._1C9Wka_label { white-space:normal !important; flex-wrap:wrap; }
}

      #dsh-rail-toggle{
        position:fixed;left:6px;top:6px;z-index:120;
        width:26px;height:26px;padding:0;border-radius:8px;cursor:pointer;
        border:1px solid color-mix(in srgb, currentColor 22%, transparent);
        background:color-mix(in srgb, currentColor 8%, transparent);
        color:inherit;font:13px/1 system-ui,sans-serif;
        display:flex;align-items:center;justify-content:center;
        opacity:.4;transition:opacity .15s ease;
      }
      #dsh-rail-toggle:hover{opacity:1}
      html[data-dsh-sidebar="hidden"] .pI_x6G_sidebarCol{visibility:hidden}
      /* —— 追加：字号整体稍大一档 + 用户消息铺满宽度 —— */
      #root{zoom:1.07}
      .Sixlwa_userStack{max-width:100% !important}
      .Sixlwa_userRow{align-items:stretch !important}
      .Sixlwa_bubble{max-width:100% !important}
      /* 输入框出现时轻微上滑淡入（display 切换会重启动画） */
      .wSkVaW_composerSeat{animation:dsh-composer-in .18s ease}
      @keyframes dsh-composer-in{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:none}}


      html[data-dsh-sidebar="full"] .pI_x6G_sidebarCol{
        z-index:100;visibility:visible !important;
        background:var(--dsw-alias-bg-base,#fff);
        box-shadow:6px 0 24px rgba(0,0,0,.28);
        animation:dsh-sidebar-in .16s ease-out;
      }
      @keyframes dsh-sidebar-in{from{transform:translateX(-10px);opacity:.6}to{transform:none;opacity:1}}
      /* 内容列反向左移同样宽度 + 铺满视口 → 视觉位置完全不变（内容不会被挤走） */
      html[data-dsh-sidebar="full"] .pI_x6G_centerCol{
        width:100vw !important;
        margin-left:calc(-1 * var(--dsh-sidebar-w,280px)) !important;
      }
      /* Brand content is supplied by the dsb-brand sidebar slots. */
      button.hHd-Xa_brand, .hHd-Xa_brand *{pointer-events:none !important}
      button.hHd-Xa_brand{cursor:default !important}

#dsh-composer-dot{display:none !important}
#dsh-tobottom-keep{
        position:fixed;right:10px;bottom:10px;z-index:2147483000;
        width:34px;height:34px;padding:0;border-radius:50%;cursor:pointer;
        border:1px solid color-mix(in srgb, currentColor 22%, transparent);
        background:color-mix(in srgb, currentColor 10%, transparent);
        color:inherit;display:flex;align-items:center;justify-content:center;
        opacity:.85;transition:opacity .15s ease, bottom .15s ease;
      }
#dsh-tobottom-keep:hover{opacity:1}
#dsh-tobottom-keep svg{width:18px;height:18px}
[aria-label="回到底部"]{display:none !important}

(function () {
  var FALLBACK_FULL = 280;
  var lastFull = FALLBACK_FULL + 'px';   // 注意带单位：无单位 width 无效（踩过）
  function frame() { return document.querySelector('div[style*="grid-template-columns"]'); }
  function appRoot() { return document.querySelector('.hHd-Xa_root'); }
  function appExpanded() { var r = appRoot(); return !!r && !r.classList.contains('hHd-Xa_collapsed'); }
  function apply() {
    var f = frame(); if (!f) return;
    var parts = (f.style.gridTemplateColumns || '').split(/\s+/);
    if (parts.length < 3) return;
    var cur = parseFloat(parts[0]) || 0;
    if (cur >= 120) lastFull = cur + 'px';
    // 展开/隐藏以 App 自己的 collapsed 类为准（它决定渲染窄条还是完整侧栏）
    var mode = appExpanded() ? 'full' : 'hidden';
    var want = mode === 'hidden' ? '0px' : lastFull;
    if (parts[0] !== want) { parts[0] = want; f.style.gridTemplateColumns = parts.join(' '); }
    document.documentElement.style.setProperty('--dsh-sidebar-w', lastFull);
    document.documentElement.setAttribute('data-dsh-sidebar', mode);
    var b = document.getElementById('dsh-rail-toggle');
    if (b) {
      b.textContent = mode === 'hidden' ? '\u203a' : '\u2039';
