  }
  function hide() {
    if (mode() !== 'shown') return;
    // 2026-09-21：手动点右下角开关后 1.5 秒内不要自动收起，否则会和手动切换打架
    // （实测：手动收起后它会把输入框又弹回来）
    if (Date.now() - (window.__dshManualToggleAt || 0) < 1500) return;
    var dot = document.getElementById('dsh-composer-dot');
    if (dot) dot.click();          // 复用右下角小圆点的切换
  }
  setInterval(function () {
